import { FormActionsProps } from '@/types/FormActions.types';
import { JSX } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

function FormActions({
  disabled,
  submitButtonText,
  cancelButtonText,
  onCancel,
  cancelBtnClassName,
  submitBtnClassName,
}: FormActionsProps): JSX.Element {
  const submitButtonWidth = cancelButtonText && onCancel ? 'w-1/2' : 'w-full';

  return (
    <div className="flex gap-4 mt-4">
      <Button
        type="submit"
        disabled={disabled}
        aria-label="Submit"
        aria-disabled={disabled}
        className={cn(submitButtonWidth, submitBtnClassName)}
      >
        {submitButtonText}
      </Button>
      {cancelButtonText && onCancel && (
        <Button
          type="button"
          onClick={onCancel}
          aria-label="Cancel"
          aria-disabled={disabled}
          disabled={disabled}
          className={cn('w-1/2', cancelBtnClassName)}
        >
          {cancelButtonText}
        </Button>
      )}
    </div>
  );
}

export default FormActions;

import {
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { cn } from '@/lib/utils';
import { FieldValues, Path } from 'react-hook-form';
import { FormFieldWrapperProps } from '@/types/FormFieldWrapper.types';
import { JSX } from 'react';

function FormFieldWrapper<T extends FieldValues>({
  formField,
}: FormFieldWrapperProps<T>): JSX.Element {
  const {
    name,
    label,
    render: renderField,
    width = 'full',
    description,
  } = formField;

  return (
    <FormField<T, Path<T>>
      name={name}
      render={({ field }) => (
        <FormItem className={cn(width === 'half' ? 'w-1/2' : 'w-full')}>
          <FormLabel>{label}</FormLabel>
          <FormControl>{renderField(field)}</FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

export default FormFieldWrapper;

import { GenericFormProps } from '@/types/GenericForm.types';
import { zodResolver } from '@hookform/resolvers/zod';
import { useForm, DefaultValues } from 'react-hook-form';
import { z, ZodObject } from 'zod';
import { Form } from '@/components/ui/form';
import { cn } from '@/lib/utils';
import { JSX } from 'react';
import { getLayoutClassName } from './utils';
import FormActions from './FormActions';
import FormFieldWrapper from './FormFieldWrapper';

function GenericForm<T extends ZodObject<{ [key: string]: z.ZodTypeAny }>>({
  formConfig,
  formSettings,
  layoutSettings,
  actions,
}: GenericFormProps<T>): JSX.Element {
  const { formFields, validationSchema, defaultValues } = formConfig;
  const { layout = 'flex', columns, gap } = layoutSettings ?? {};
  const { mode = 'onSubmit', disabled, className } = formSettings ?? {};
  const {
    submitButtonText = 'Submit',
    cancelButtonText,
    onSubmit,
    onError,
    onCancel,
    cancelBtnClassName,
    submitBtnClassName,
  } = actions;

  const form = useForm<z.input<T>, any, z.output<T>>({
    resolver: zodResolver(validationSchema),
    defaultValues: defaultValues as DefaultValues<z.input<T>>,
    mode,
    disabled,
  });

  const values = form.watch();

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit, onError)}
        className={cn('space-y-4', className)}
      >
        <div className={getLayoutClassName(layout, columns, gap)}>
          {formFields.map((formField) => {
            if (formField.condition && !formField.condition(values))
              return null;

            return (
              <FormFieldWrapper<z.input<T>>
                key={formField.name}
                formField={formField}
              />
            );
          })}
        </div>
        <FormActions
          submitButtonText={submitButtonText}
          cancelButtonText={cancelButtonText}
          submitBtnClassName={submitBtnClassName}
          cancelBtnClassName={cancelBtnClassName}
          disabled={disabled}
          onCancel={onCancel}
        />
      </form>
    </Form>
  );
}

export default GenericForm;

import { GAPS, GRID_COLS } from './constants';
import { cn } from '@/lib/utils';

export const getLayoutClassName = (
  layout: 'grid' | 'flex',
  columns?: number,
  gap?: number
) => {
  const colClass = GRID_COLS[columns || 2] || 'grid-cols-2';
  const gapClass = GAPS[gap || 4] || 'gap-4';

  return cn(
    layout === 'grid' ? 'grid' : 'flex flex-wrap',
    layout === 'grid' ? `${colClass} ${gapClass}` : gapClass
  );
};

export interface FormActionsProps {
  disabled?: boolean;
  submitButtonText: string;
  cancelButtonText?: string;
  onCancel?: () => void;
  submitBtnClassName?: string;
  cancelBtnClassName?: string;
}

import { ControllerRenderProps, FieldValues, Path } from 'react-hook-form';

export interface FormFieldConfig<T extends FieldValues> {
  name: Path<T>;
  label: string;
  render: (field: ControllerRenderProps<T, Path<T>>) => React.ReactElement;
  width?: 'full' | 'half' | string;
  condition?: (values: T) => boolean;
  description?: string;
}

import { FieldValues } from 'react-hook-form';
import { FormFieldConfig } from './FormField.types';

export interface FormFieldWrapperProps<T extends FieldValues> {
  formField: FormFieldConfig<T>;
}

import { z, ZodObject, ZodRawShape } from 'zod';
import { DefaultValues } from 'react-hook-form';
import { FormFieldConfig } from './FormField.types';

export interface GenericFormProps<T extends ZodObject<ZodRawShape>> {
  formConfig: {
    formFields: FormFieldConfig<z.input<T>>[];
    validationSchema: T;
    defaultValues: DefaultValues<z.input<T>>;
  };

  formSettings?: {
    mode?: 'onSubmit' | 'onBlur' | 'onChange' | 'onTouched' | 'all';
    disabled?: boolean;
    className?: string;
  };

  layoutSettings?: {
    layout?: 'flex' | 'grid';
    columns?: number;
    gap?: number;
  };

  actions: {
    submitButtonText?: string;
    cancelButtonText?: string;
    submitBtnClassName?: string;
    cancelBtnClassName?: string;
    onSubmit: (values: z.output<T>) => void;
    onError?: (errors: Record<string, unknown>) => void;
    onCancel?: () => void;
  };
}

export default GenericFormProps;
